def quick_select(arr, k):
    # returns the kth smallest element (k is 1 based)
    lo, hi = 0, len(arr) - 1
    target = k - 1
    while lo <= hi:
        p = partition(arr, lo, hi)
        if p == target:
            return arr[p]
        elif p < target:
            lo = p + 1      # the answer is on the right
        else:
            hi = p - 1      # the answer is on the left
